import{_ as o,a0 as a,w as p,s as l,ao as d,I as s,x as n,a1 as i,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"每日Ubuntu小技巧：Ubuntu下一款和Windows磁盘管理一样的工具 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧：Ubuntu下一款和Windows磁盘管理一样的工具 | LCTT (201401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧：Ubuntu下一款和Windows磁盘管理一样的工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧：Ubuntu下一款和Windows磁盘管理一样的工具 | LCTT (201401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201401/Daily Ubuntu Tips — Windows Disk Management Equivalent In Ubuntu","title":"每日Ubuntu小技巧：Ubuntu下一款和Windows磁盘管理一样的工具","tag":"201401","desc":""},"relativePath":"201401/Daily Ubuntu Tips — Windows Disk Management Equivalent In Ubuntu.md","filePath":"[post].md"}'),r={name:"201401/Daily Ubuntu Tips — Windows Disk Management Equivalent In Ubuntu.md"};function b(w,t,m,U,T,g){const u=a("Link");return p(),l("div",null,[t[11]||(t[11]=d('<h1 id="每日ubuntu小技巧-ubuntu下一款和windows磁盘管理一样的工具" tabindex="-1">每日Ubuntu小技巧：Ubuntu下一款和Windows磁盘管理一样的工具 <a class="header-anchor" href="#每日ubuntu小技巧-ubuntu下一款和windows磁盘管理一样的工具" aria-label="Permalink to “每日Ubuntu小技巧：Ubuntu下一款和Windows磁盘管理一样的工具”">​</a></h1><p>对于一些用惯了Windows的用户来说，刚开始接触Ubuntu的时候会面临这样的一个问题，这个问题在很多论坛里面也经常出现，前段时间也有位读者问到相同的问题：</p><blockquote><p>在 Ubuntu 中有和 Windows 下的磁盘管理一样的工具么？</p></blockquote><p>对于那些不太清楚磁盘管理的用户，下面有个简单介绍。</p><p>磁盘管理是一个从 Windows XP 起就有的默认工具，其主要负责磁盘相关的任务，比如：创建和格式化磁盘、初始化磁盘，重新划分磁盘大小和指定分区号以及删除分区。</p><p>在 Windows 下用户使用和磁盘分区管理相关的命令行工具进行磁盘操作，这个工具很高大上。</p><p>问题是在 Ubuntu 系统下有这样的工具么，答案是肯定滴。</p><p>Ubuntu 下有个很相似的软件叫做 GNOME Disk Utility ，这个工具同样能尽心查看/管理你的磁盘分区，以及创建和恢复分区。你同样可以用它进行创建和格式化分区，挂载和卸载卷组以及其它相关的磁盘操作。</p><p>尽管这和Windows下的管理工具相似，但是它不允许用户重新定义分区和卷组大小，因为 ubuntu 不支持驱动器号。</p><p>所以，想在 Ubuntu 系统下使用类似 windows 下的磁盘管理工具，那就试试 GNOME Disk Utility 吧。</p><p>你可以在 Unity Dash 中搜索 <strong>硬盘</strong> ，打开时，它会自己识别你电脑上的外部硬盘和额外的硬盘驱动器。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/01/dropboxubuntumissingfolder3.png" alt=""></p><p>一旦驱动器被选择你就可以进行磁盘相关的操作了，比如：格式化、创建分区，管理驱动器。另外在磁盘访问超时情况下一些待机模式的操作。</p><p>需要注意的是，当你格式化一个磁盘让它既可以在 Windows 下又可以在 Ubuntu 下使用时，一定要选择 NTFS 文件系统。</p><p>那么，在 Ubuntu 下使用磁盘配置你的驱动器吧。</p><p>慢慢享用，新年快乐！</p><hr>',17)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),i(u,{href:"http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-windows-disk-management-equivalent-in-ubuntu/"},{default:e(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2014/01/daily-ubuntu-tips-windows-disk-management-equivalent-in-ubuntu/",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=n("译者：",-1)),i(u,{href:"https://github.com/Timeszoro"},{default:e(()=>[...t[2]||(t[2]=[n("Timeszoro",-1)])]),_:1}),t[5]||(t[5]=n(" 校对：",-1)),i(u,{href:"https://github.com/carolinewuyan"},{default:e(()=>[...t[3]||(t[3]=[n("Caroline",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=n("本文由 ",-1)),i(u,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原创翻译，",-1)),i(u,{href:"http://linux.cn/"},{default:e(()=>[...t[7]||(t[7]=[n("Linux中国",-1)])]),_:1}),t[10]||(t[10]=n(" 荣誉推出",-1))])])}const D=o(r,[["render",b]]);export{C as __pageData,D as default};
